def p(text, style='BodyCustom'):
    return Paragraph(text, styles[style])

def title(name, subtitle):
    return [p('E-MEDICAPP', 'BrandCustom'), p(name, 'TitleCustom'), p(subtitle, 'SubCustom')]

def h(text): return p(text, 'HCustom')
def h2(text): return p(text, 'H2Custom')
def body(text): return p(text)
def small(text): return p(text, 'SmallCustom')
def page(): return PageBreak()

def table(headers, rows, widths):
    data = [[p(escape(x), 'THCustom') for x in headers]]
    data += [[p(str(v), 'CellCustom') for v in row] for row in rows]
    t = Table(data, colWidths=widths, repeatRows=1, hAlign='LEFT')
    commands = [('BACKGROUND',(0,0),(-1,0),NAVY), ('GRID',(0,0),(-1,-1),0.5,LINE), ('VALIGN',(0,0),(-1,-1),'MIDDLE'), ('LEFTPADDING',(0,0),(-1,-1),9), ('RIGHTPADDING',(0,0),(-1,-1),9), ('TOPPADDING',(0,0),(-1,-1),8), ('BOTTOMPADDING',(0,0),(-1,-1),8)]
    for idx in range(1,len(data)):
        if idx % 2 == 0: commands.append(('BACKGROUND',(0,idx),(-1,idx),LIGHT))
    t.setStyle(TableStyle(commands))
    t.spaceAfter = 10
    return t

class NumberedCanvas(canvas.Canvas):
    def __init__(self,*a,**kw):
        super().__init__(*a,**kw)
        self._saved = []
    def showPage(self):
        self._saved.append(dict(self.__dict__))
        self._startPage()
    def save(self):
        total=len(self._saved)
        for state in self._saved:
            self.__dict__.update(state)
            self.setFont('Arial',8)
            self.setFillColor(GREY)
            self.drawString(48,30,'E-MEDICAPP / 19 de octubre de 2026')
            self.drawRightString(A4[0]-48,30,f'{self._pageNumber} / {total}')
            super().showPage()
        super().save()

def save(name, story):
    path=OUT/name
    doc=SimpleDocTemplate(str(path), pagesize=A4, rightMargin=48, leftMargin=48, topMargin=43, bottomMargin=49, title=name.split('_',1)[-1].replace('_',' ').removesuffix('.pdf'), author='E-MEDICAPP', subject='Presentación del proyecto al 19 de octubre de 2026')
    doc.build(story,canvasmaker=NumberedCanvas)
    return path

def link(label, url):
    return f'<a href="{escape(url)}" color="#163D4B">{escape(label)}</a>'

