files=[plan,finance,summary,annex]
manifest=[]
for path in files:
    r=PdfReader(path)
    texts=[pg.extract_text() or '' for pg in r.pages]
    assert all(text.strip() for text in texts)
    assert path.stat().st_size < 10_000_000
    assert not r.get_fields()
    manifest.append({'file':path.name,'pages':len(r.pages),'bytes':path.stat().st_size,'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'chars_per_page':[len(t) for t in texts]})
(TMP/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(manifest,ensure_ascii=False,indent=2))
